import unittest

from inventory import summarize


class InventoryTests(unittest.TestCase):
    def test_repeated_skus_are_summed(self):
        records = [
            {"sku": "x", "quantity": 2},
            {"sku": "y", "quantity": 3},
            {"sku": "x", "quantity": 4},
            {"sku": "y", "quantity": -1},
            {"sku": "z", "quantity": 0},
        ]
        self.assertEqual(summarize(records), {"x": 6, "y": 2, "z": 0})

    def test_one_pass_iterable(self):
        class OnePass:
            def __init__(self):
                self.started = False

            def __iter__(self):
                if self.started:
                    raise AssertionError("Input must only be iterated once")
                self.started = True
                return iter([
                    {"sku": "x", "quantity": 2},
                    {"sku": "y", "quantity": 1},
                    {"sku": "x", "quantity": 4},
                ])

        self.assertEqual(summarize(OnePass()), {"x": 6, "y": 1})

    def test_empty_input(self):
        self.assertEqual(summarize([]), {})
        self.assertEqual(summarize(iter(())), {})

