import io
import json
import unittest

from exporter import write_batch
from recovery import write_recovery
from wire_formats import decode


class ExportDefaultsTests(unittest.TestCase):
    def setUp(self):
        self.rows = [{"id": "s-1", "sku": "part,blue", "quantity": 4}]

    def inputs(self, writer):
        if writer is write_batch:
            return (dict(row) for row in self.rows)
        return iter([
            {"op": "upsert", **self.rows[0], "quantity": 2},
            {"op": "upsert", **self.rows[0]},
            {"op": "upsert", "id": "s-2", "sku": "removed", "quantity": 1},
            {"op": "delete", "id": "s-2"},
        ])

    def assert_output(self, output, fmt):
        if fmt == "csv-v1":
            self.assertEqual(output.splitlines()[0], "id,sku,quantity")
        else:
            self.assertEqual(json.loads(output), {"version": 2, **self.rows[0]})
        self.assertEqual(decode(io.StringIO(output), fmt), self.rows)

    def test_site_defaults_for_normal_and_recovery_iterables(self):
        for writer in (write_batch, write_recovery):
            for site, fmt in (("north", "csv-v1"), ("south", "jsonl-v2"),
                              ("new-site", "jsonl-v2")):
                with self.subTest(writer=writer.__name__, site=site):
                    out = io.StringIO()
                    writer(site, self.inputs(writer), out)
                    self.assert_output(out.getvalue(), fmt)

    def test_explicit_formats_override_site_defaults(self):
        for writer in (write_batch, write_recovery):
            for site in ("north", "south", "new-site"):
                for fmt in ("csv-v1", "jsonl-v2"):
                    with self.subTest(writer=writer.__name__, site=site, fmt=fmt):
                        out = io.StringIO()
                        writer(site, self.inputs(writer), out, format_name=fmt)
                        self.assert_output(out.getvalue(), fmt)

    def test_empty_iterables(self):
        for writer in (write_batch, write_recovery):
            for site in ("north", "new-site"):
                with self.subTest(writer=writer.__name__, site=site):
                    out = io.StringIO()
                    writer(site, iter(()), out)
                    expected = "id,sku,quantity\r\n" if site == "north" else ""
                    self.assertEqual(out.getvalue(), expected)

    def test_invalid_explicit_format_is_rejected(self):
        for writer in (write_batch, write_recovery):
            for fmt in ("unknown", ""):
                with self.subTest(writer=writer.__name__, fmt=fmt):
                    with self.assertRaisesRegex(ValueError, "Unsupported format:"):
                        writer("north", self.inputs(writer), io.StringIO(), fmt)

    def test_batch_consumes_records_incrementally(self):
        for site in ("north", "new-site"):
            with self.subTest(site=site):
                out = io.StringIO()

                def records():
                    yield self.rows[0]
                    self.assertIn("s-1", out.getvalue())
                    yield {"id": "s-2", "sku": "second", "quantity": 1}

                write_batch(site, records(), out)
                fmt = "csv-v1" if site == "north" else "jsonl-v2"
                self.assertEqual(len(decode(io.StringIO(out.getvalue()), fmt)), 2)

