        self.events = [
            {"op": "delete", "id": "missing"},
            {"op": "upsert", "id": "s-1", "sku": "old", "quantity": 1},
            {"op": "upsert", "id": "s-2", "sku": "removed", "quantity": 2},
            {"op": "upsert", "id": "s-1", "sku": "part,blue", "quantity": 4},
            {"op": "delete", "id": "s-2"},
            {"op": "upsert", "id": "s-3", "sku": "old", "quantity": 3},
            {"op": "delete", "id": "s-3"},
            {"op": "upsert", "id": "s-3", "sku": "restored", "quantity": 5},
        ]
        self.rows = [
            {"id": "s-1", "sku": "part,blue", "quantity": 4},
            {"id": "s-3", "sku": "restored", "quantity": 5},
        ]

    def assert_output(self, output, fmt):
        self.assertEqual(decode(io.StringIO(output), fmt), self.rows)
        if fmt == "jsonl-v2":
            self.assertEqual(
                [json.loads(line) for line in output.splitlines()],
                [{"version": 2, **row} for row in self.rows],
            )
        else:
            self.assertEqual(output.splitlines()[0], "id,sku,quantity")

    def test_site_defaults_reduce_generator_journal(self):
        for site, fmt in (("north", "csv-v1"), ("south", "jsonl-v2"),
                          ("new-site", "jsonl-v2")):
            for args in ((), (None,)):
                with self.subTest(site=site, args=args):
                    out = io.StringIO()
                    write_recovery(site, iter(self.events), out, *args)
                    self.assert_output(out.getvalue(), fmt)

    def test_explicit_formats_override_site_defaults(self):
        for site in ("north", "south", "new-site"):
            for fmt in ("csv-v1", "jsonl-v2"):
                with self.subTest(site=site, fmt=fmt):
                    out = io.StringIO()
                    write_recovery(site, iter(self.events), out, format_name=fmt)
                    self.assert_output(out.getvalue(), fmt)

    def test_invalid_explicit_format_is_not_defaulted(self):
        for fmt in ("", "unknown"):
            with self.subTest(fmt=fmt):
                with self.assertRaisesRegex(ValueError, "Unsupported format:"):
                    write_recovery("north", iter(self.events), io.StringIO(), fmt)

    def test_unknown_operation_still_fails(self):
        out = io.StringIO()
        with self.assertRaisesRegex(ValueError, "Unknown event operation"):
            write_recovery("new-site", [{"op": "unknown"}], out)
        self.assertEqual(out.getvalue(), "")

    def test_empty_recovery_image(self):
        for site, expected in (("north", "id,sku,quantity\r\n"),
                               ("new-site", "")):
            for events in ([], [self.events[1], {"op": "delete", "id": "s-1"}]):
                with self.subTest(site=site, events=events):
                    out = io.StringIO()
                    write_recovery(site, iter(events), out)
                    self.assertEqual(out.getvalue(), expected)

    def test_normal_export_defaults_remain_csv(self):
        for site in ("north", "south", "new-site"):
            with self.subTest(site=site):
                out = io.StringIO()
                write_batch(site, iter(self.rows), out)
                self.assert_output(out.getvalue(), "csv-v1")

