class RoutingTests(unittest.TestCase):
    rows = [{"id": "s-1", "sku": "part,blue", "quantity": 2}]

    def export(self, writer, site, **kwargs):
        records = self.rows
        if writer is write_recovery:
            records = [{"op": "upsert", **row} for row in records]
        out = io.StringIO()
        writer(site, (row for row in records), out, **kwargs)
        return out.getvalue()

    def assert_format(self, payload, fmt):
        self.assertEqual(decode(io.StringIO(payload), fmt), self.rows)
        if fmt == "csv-v1":
            self.assertTrue(payload.startswith("id,sku,quantity\r\n"))
        else:
            self.assertEqual(json.loads(payload)["version"], 2)

    def test_defaults_for_both_export_paths(self):
        for writer in (write_batch, write_recovery):
            for site, fmt in (("north", "csv-v1"), ("south", "jsonl-v2"),
                              ("new-site", "jsonl-v2")):
                for kwargs in ({}, {"format_name": None}):
                    with self.subTest(writer=writer.__name__, site=site, kwargs=kwargs):
                        self.assert_format(self.export(writer, site, **kwargs), fmt)

    def test_explicit_overrides_for_both_export_paths(self):
        for writer in (write_batch, write_recovery):
            for site in ("north", "south", "new-site"):
                for fmt in ("csv-v1", "jsonl-v2"):
                    with self.subTest(writer=writer.__name__, site=site, fmt=fmt):
                        self.assert_format(self.export(writer, site, format_name=fmt), fmt)

    def test_invalid_explicit_format_is_not_replaced_by_default(self):
        for writer in (write_batch, write_recovery):
            for fmt in ("", "unknown"):
                with self.subTest(writer=writer.__name__, fmt=fmt):
                    with self.assertRaisesRegex(ValueError, "Unsupported format:"):
                        self.export(writer, "north", format_name=fmt)

    def test_batch_consumes_generator_incrementally(self):
        for site in ("north", "new-site"):
            with self.subTest(site=site):
                out = io.StringIO()

