            {"op": "upsert", "id": "s-2", "sku": "deleted", "quantity": 1},
            {"op": "upsert", "id": "s-1", "sku": "part,blue\nnew", "quantity": 4},
            {"op": "delete", "id": "s-2"},
            {"op": "delete", "id": "s-2"},
        ]
        self.rows = [{"id": "s-1", "sku": "part,blue\nnew", "quantity": 4}]

    def test_shared_jsonl_default_including_former_exception(self):
        for site in ("new-site", "north"):
            for writer, records in ((write_batch, self.rows),
                                    (write_recovery, self.events)):
                with self.subTest(site=site, writer=writer.__name__):
                    out = io.StringIO()
                    writer(site, iter(records), out)
                    self.assertEqual(
                        [json.loads(line) for line in out.getvalue().splitlines()],
                        [{"version": 2, **row} for row in self.rows],
                    )

    def test_recovery_explicit_overrides(self):
        for site in ("new-site", "north"):
            for fmt in ("csv-v1", "jsonl-v2"):
                with self.subTest(site=site, format=fmt):
                    out = io.StringIO()
                    write_recovery(site, iter(self.events), out, format_name=fmt)
                    self.assertEqual(decode(io.StringIO(out.getvalue()), fmt), self.rows)

    def test_empty_or_deleted_image(self):
        for events in ([], self.events + [{"op": "delete", "id": "s-1"}]):
            with self.subTest(events=events):
                out = io.StringIO()
                write_recovery("new-site", iter(events), out)
                self.assertEqual(out.getvalue(), "")

    def test_upsert_after_delete_restores_latest_image(self):
        events = self.events + [
            {"op": "upsert", "id": "s-2", "sku": "restored", "quantity": 3}
        ]
        out = io.StringIO()
        write_recovery("north", iter(events), out)
        self.assertEqual(
            decode(io.StringIO(out.getvalue()), "jsonl-v2"),
            self.rows + [{"id": "s-2", "sku": "restored", "quantity": 3}],
        )

    def test_invalid_operation_does_not_write_partial_image(self):
